/// TFM metric table of a Computer Modern face, or `None` for faces without TFM data
/// (Base-14 faces, Dingbats). `Face::Mono` is cmtt10 under Computer Modern.
///
/// This is the single face -> table dispatch for the CM path: the TeX rule that the
/// width, height, depth and italic correction come from the font actually selected at the
/// current size holds as long as callers resolve the optical face first.
#[inline]
pub fn cm_face_table(face: Face) -> Option<&'static [PackedGlyphMetric; 128]> {
    use crate::math::math_tfm as t;
    Some(match face {
        Face::Roman => &t::CMR10_METRICS,
        Face::Roman7 => &t::CMR7_METRICS,
        Face::Roman5 => &t::CMR5_METRICS,
        Face::Bold => &t::CMBX10_METRICS,
        Face::Italic => &t::CMTI10_METRICS,
        Face::MathItalic => &t::CMMI10_METRICS,
        Face::MathItalic7 => &t::CMMI7_METRICS,
        Face::MathItalic5 => &t::CMMI5_METRICS,
        Face::Symbol => &t::CMSY10_METRICS,
        Face::Symbol7 => &t::CMSY7_METRICS,
        Face::Symbol5 => &t::CMSY5_METRICS,
        Face::Extension => &t::CMEX10_METRICS,
        Face::AmsA => &t::MSAM10_METRICS,
        Face::AmsB => &t::MSBM10_METRICS,
        Face::Mono => &CMTT10_METRICS,
        Face::MathMono8 => &CMTT8_METRICS,
        Face::MathSans => &CMSS10_METRICS,
        Face::MathSans8 => &CMSS8_METRICS,
        Face::Fraktur => &EUFM10_METRICS,
        Face::Fraktur7 => &EUFM7_METRICS,
        Face::Fraktur5 => &EUFM5_METRICS,
        Face::BoldMathItalic => &CMMIB10_METRICS,
        Face::BoldMathItalic7 => &CMMIB7_METRICS,
        Face::BoldMathItalic5 => &CMMIB5_METRICS,
        Face::BoldSymbol => &CMBSY10_METRICS,
        Face::BoldSymbol7 => &CMBSY7_METRICS,
        Face::BoldSymbol5 => &CMBSY5_METRICS,
        Face::Extension7 => &CMEX7_METRICS,
        Face::SmallCaps => &CMCSC10_METRICS,
        Face::BoldItalic | Face::MonoBold | Face::Dingbats => return None,
    })
}

